starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "bucket_name" {
  description = "Input variable bucket_name."
  type        = string
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_s3_bucket_versioning" "this" {
  # TODO - Complete the aws_s3_bucket_versioning resource.
  # Add the arguments and nested blocks required for aws_s3_bucket_versioning.
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = var.bucket_name
  rule {
    status = "Enabled"
    expiration {
      days = 30
    }
  }
}
